def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # lower objective is better; keep only pairs with a clear margin and cap per-instance pairs
    if extra is None:
        extra = {}

    # Avoid using Python builtins like float/int (may be stripped from the eval env).
    gap_threshold = extra.get('gap_threshold', 0.02)
    max_pairs_per_instance = extra.get('max_pairs_per_instance', 2048)

    # diff[b,i,j] = obj[b,j] - obj[b,i]; positive means i is better than j by that gap.
    diff = objective[:, None, :] - objective[:, :, None]
    mask = diff > gap_threshold
    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)

    # Cap pairs per instance deterministically to avoid overweighting large candidate sets.
    if b_idx.numel() > 0 and max_pairs_per_instance is not None:
        if max_pairs_per_instance <= 0:
            empty = objective.new_zeros((0,), dtype=b_idx.dtype)
            return PrefBatch(
                mode='pairwise',
                pair_idx=(empty, empty, empty),
                weight=None,
                meta={
                    'builder': 'gap_threshold_pairs_capped',
                    'gap_threshold': gap_threshold,
                    'max_pairs_per_instance': max_pairs_per_instance,
                },
            )

        n_b = objective.shape[0]
        keep = objective.new_zeros((b_idx.numel(),), dtype=torch.bool)
        counts = objective.new_zeros((n_b,), dtype=torch.long)
        t = 0
        while t < b_idx.numel():
            b = b_idx[t].to(dtype=torch.long)
            if counts[b] < max_pairs_per_instance:
                keep[t] = True
                counts[b] = counts[b] + 1
            t = t + 1

        b_idx = b_idx[keep]
        winner_idx = winner_idx[keep]
        loser_idx = loser_idx[keep]

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, winner_idx, loser_idx),
        weight=None,
        meta={
            'builder': 'gap_threshold_pairs_capped',
            'gap_threshold': gap_threshold,
            'max_pairs_per_instance': max_pairs_per_instance,
        },
    )

