    if extra is not None and extra.get('mid_frac', None) is not None:
        mid_frac = extra.get('mid_frac')

    # Clamp fractions to sensible ranges without randomness.
    if top_frac < 0:
        top_frac = 0
    if top_frac > 1:
        top_frac = 1
    if mid_frac < 0:
        mid_frac = 0
    if mid_frac > 1:
        mid_frac = 1

    # Determine tier sizes (at least 1 element if K>0).
    top_n = int(K * top_frac)
