    sorted_idx = objective.argsort(dim=1)

    top_idx = sorted_idx[:, :top_n]
    mid_idx = sorted_idx[:, top_n:mid_n]
    tail_idx = sorted_idx[:, mid_n:]

    b_list = []
    w_list = []
    l_list = []

    # Deterministic pairing: take a few representatives from each tier.
    # - best beats some mid and some tail
    # - mid beats some tail
    for b in range(B):
        pairs_left = max_pairs_per_instance

        # Helper to append a pair
        def _add_pair(wi, li):
