            for i in range(top_take):
                if pairs_left <= 0:
                    break
                wi = top_idx[b, i]
                # Pair against first mid elements
                for j in range(mid_take):
                    if pairs_left <= 0:
                        break
                    li = mid_idx[b, j]
                    _add_pair(wi, li)
                    pairs_left -= 1

        # best > tail
        if pairs_left > 0 and top_take > 0 and tail_take > 0:
            for i in range(top_take):
                if pairs_left <= 0:
                    break
                wi = top_idx[b, i]
                for j in range(tail_take):
                    if pairs_left <= 0:
                        break
                    li = tail_idx[b, j]
                    _add_pair(wi, li)
                    pairs_left -= 1

        # mid > tail (if mid exists)
        if pairs_left > 0 and mid_take > 0 and tail_take > 0:
