                    break
                wi = mid_idx[b, i]
                for j in range(tail_take):
                    if pairs_left <= 0:
                        break
                    li = tail_idx[b, j]
                    _add_pair(wi, li)
                    pairs_left -= 1

        # Fallback: if no pairs were formed (e.g., K<2), do nothing.

    if len(b_list) == 0:
        # Produce an empty but well-typed PrefBatch.
        empty = objective.new_empty((0,), dtype=torch.long)
        meta = {
            'builder': 'rank_stratified_capped_pairs',
            'max_pairs_per_instance': max_pairs_per_instance,
            'top_frac': top_frac,
            'mid_frac': mid_frac,
            'note': 'no_pairs_possible'
        }
        return PrefBatch(mode='pairwise', pair_idx=(empty, empty, empty), weight=None, meta=meta)

    b_idx = torch.tensor(b_list, device=objective.device, dtype=torch.long)
    winner_idx = torch.tensor(w_list, device=objective.device, dtype=torch.long)
    loser_idx = torch.tensor(l_list, device=objective.device, dtype=torch.long)

    meta = {
        'builder': 'rank_stratified_capped_pairs',
